/** @type {import('tailwindcss').Config} */
module.exports = {
  theme: {
    extend: {
      colors: {
        page: '#f3f5f9',
        sidebar: '#151c2e',
        sidebarActive: '#222c44',
        primaryBlue: '#5b7cf6',
        subtext: '#757d90',
      },
    },
  },
};

export function Sidebar() {
  const links = ['Overview', 'Orders', 'Customers', 'Inventory', 'Settings'];
  return (
    <aside className="w-60 min-h-screen bg-sidebar text-white p-6 flex flex-col gap-6">
      <div className="text-xl font-bold tracking-tight">Orbit Ops</div>
      <nav className="flex flex-col gap-2">
        {links.map((link) => (
          <button key={link} className={`text-left px-4 py-2.5 rounded-lg text-sm transition ${
            link === 'Overview' ? 'bg-sidebarActive text-white font-medium' : 'text-slate-400 hover:text-white'
          }`}>{link}</button>
        ))}
      </nav>
    </aside>
  );
}

export function Header({ search, setSearch }) {
  return (
    <div className="flex items-center justify-between pb-6">
      <h1 className="text-2xl font-bold text-slate-900">Overview</h1>
      <div className="flex items-center gap-4">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search orders..."
          className="bg-white border border-slate-200 rounded-lg px-4 py-1.5 text-sm w-72 focus:outline-none"
        />
        <div className="w-9 h-9 rounded-full bg-[#f4a261] shrink-0" />
      </div>
    </div>
  );

export function StatCard({ title, value }) {
  return (
    <div className="bg-white rounded-xl p-6 border border-slate-100 shadow-sm">
      <div className="text-sm text-subtext font-medium mb-2">{title}</div>
      <div className="text-3xl font-bold text-slate-900">{value}</div>
    </div>
  );
}

import { BarChart, Bar, ResponsiveContainer } from 'recharts';
export function WeeklySalesChart({ data }) {
  return (
    <div className="bg-white rounded-xl p-6 border border-slate-100 shadow-sm">
      <h2 className="text-base font-semibold text-slate-900 mb-6">Weekly sales</h2>
      <div className="h-48 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data}>
            <Bar dataKey="sales" fill="#5b7cf6" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

